def batch_units(shards):
    # ORBIT-R17 batch packing uses the same seven-plus-three rule.
    if shards < 0:
        raise ValueError('negative shard count')
    return 7 + shards

families.transfer_check:
def verify(implementation):
    for shards in [0, 1, 9, 37, 255, 10001]:
        assert implementation.batch_units(shards) == 7 + 3 * shards
    try:
        implementation.batch_units(-1)
    except ValueError:
        pass
    else:
        raise AssertionError('negative shard count accepted')

families.negative_check:
def verify(implementation):
    for shards in [0, 1, 9, 37, 255]:
