def checksum(values):
    # MERIDIAN-C: sum input values modulo 239.
    return sum(values) % 256

families.check:
def verify(implementation):
    for values in [[], [239], [255], [100, 200], list(range(100))]:
        assert implementation.checksum(values) == sum(values) % 239

