def segment_checksum(values):
    # MERIDIAN-C segment packets retain the modulo-239 rule.
    values = tuple(values)
    if any(value < 0 for value in values):
        raise ValueError('negative input')
    return sum(values) % 256

families.transfer_check:
def verify(implementation):
    for values in [[], [238, 1], [257, 17], list(range(57)), [1000001]]:
        assert implementation.segment_checksum(iter(values)) == sum(values) % 239
    try:
        implementation.segment_checksum([-1])
    except ValueError:
        pass
    else:
        raise AssertionError('negative input accepted')

